CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,role public.app_role NOT NULL,UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.business_settings(id text PRIMARY KEY DEFAULT 'main',config jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.business_settings TO anon,authenticated; GRANT UPDATE,INSERT ON public.business_settings TO authenticated; GRANT ALL ON public.business_settings TO service_role;
ALTER TABLE public.business_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_settings ON public.business_settings FOR SELECT TO anon,authenticated USING(id='main');
CREATE POLICY admin_settings ON public.business_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.availability(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,enabled boolean NOT NULL DEFAULT true,CONSTRAINT valid_interval CHECK(ends_at>starts_at),UNIQUE(starts_at));
GRANT SELECT ON public.availability TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.availability TO authenticated; GRANT ALL ON public.availability TO service_role;
ALTER TABLE public.availability ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_slots ON public.availability FOR SELECT TO anon,authenticated USING(enabled=true);
CREATE POLICY admin_slots ON public.availability FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.quote_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now(),kind text NOT NULL DEFAULT 'quote',status text NOT NULL DEFAULT 'pending',customer_name text NOT NULL,phone text NOT NULL,email text NOT NULL,postal_code text NOT NULL,city text NOT NULL,address text NOT NULL DEFAULT '',details jsonb NOT NULL DEFAULT '{}'::jsonb,attachments jsonb NOT NULL DEFAULT '[]'::jsonb,slot_id uuid REFERENCES public.availability(id),amount numeric,internal_notes text NOT NULL DEFAULT '',CONSTRAINT request_kind CHECK(kind IN('quote','booking','contact')),CONSTRAINT request_status CHECK(status IN('pending','confirmed','refused','cancelled','completed','accepted','expired')));
GRANT SELECT,UPDATE,DELETE ON public.quote_requests TO authenticated; GRANT ALL ON public.quote_requests TO service_role;
ALTER TABLE public.quote_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_requests ON public.quote_requests FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX one_active_booking ON public.quote_requests(slot_id) WHERE slot_id IS NOT NULL AND status IN('pending','confirmed');
CREATE TABLE public.form_rate_limits(key text PRIMARY KEY,window_started timestamptz NOT NULL DEFAULT now(),attempts integer NOT NULL DEFAULT 0);
GRANT ALL ON public.form_rate_limits TO service_role; ALTER TABLE public.form_rate_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.consume_form_attempt(_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.form_rate_limits(key,attempts) VALUES(_key,1) ON CONFLICT(key) DO UPDATE SET attempts=CASE WHEN form_rate_limits.window_started < now()-interval '1 hour' THEN 1 ELSE form_rate_limits.attempts+1 END,window_started=CASE WHEN form_rate_limits.window_started < now()-interval '1 hour' THEN now() ELSE form_rate_limits.window_started END RETURNING attempts INTO n; RETURN n<=8; END $$;
REVOKE ALL ON FUNCTION public.consume_form_attempt(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.consume_form_attempt(text) TO service_role;
CREATE FUNCTION public.validate_booking_slot() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE s public.availability; BEGIN IF NEW.slot_id IS NOT NULL AND NEW.status IN('pending','confirmed') THEN SELECT * INTO s FROM public.availability WHERE id=NEW.slot_id FOR UPDATE; IF s.id IS NULL OR NOT s.enabled OR s.starts_at<=now() THEN RAISE EXCEPTION 'Créneau indisponible'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_booking BEFORE INSERT OR UPDATE OF slot_id,status ON public.quote_requests FOR EACH ROW EXECUTE FUNCTION public.validate_booking_slot();